(* ------------------------------------------------------------------------- *)
(* One encoding of each instruction form that the x86 decoder accepts, for   *)
(* the cosimulation pools in simulator.ml, so that every form is compared    *)
(* with hardware. A form is a decoder case with its constructor (and         *)
(* condition), its operand kinds and sizes, and register or memory operands. *)
(* Each form appears with registers 1-7 (rcx to rdi, xmm1 to xmm7) and       *)
(* again, where that is encodable, with registers 8-15 (REX.R and REX.B, or  *)
(* VEX R, B and vvvv). No register appears twice among the operands of an    *)
(* entry, implicit ones included, so that a mix-up of operands would show,   *)
(* and none is RSP. Immediates are 0x15, 0x1234, 0x12345678 and              *)
(* 0x123456789abcdef0 with the low registers and 0x95, 0x9234, 0x92345678    *)
(* and 0x923456789abcdef0 with the high ones, so that sign extension is      *)
(* tested too; a form with an immediate but no high-register encoding        *)
(* appears with both. Memory operands are [rsp+32], as in the simple-memory  *)
(* pool; LEA uses [rbx+32]. The stack, branch and string forms (PUSH, POP,   *)
(* CALL, RET, Jcc, JMP and MOVSB) are left to the harnesses in simulator.ml. *)
(* Each comment gives the disassembly and the form. New decoder forms should *)
(* be added here too.                                                        *)
(* ------------------------------------------------------------------------- *)

