(* Further encodings of these forms: for each decoder case, one entry for    *)
(* each combination of prefixes (66, repeated 66, F3 or a segment override   *)
(* where it is ignored), REX (absent, W clear, W set) or VEX (C5 or C4, L    *)
(* and W) that the decoder accepts for some form of the case and that no     *)
(* other entry or harness had. Most are prefixes that the hardware ignores   *)
(* or that another one overrides, such as 66 with REX.W, or VEX.W where the  *)
(* instruction ignores it.                                                   *)
(* ------------------------------------------------------------------------- *)

